import json
from pathlib import Path
root=Path(__file__).resolve().parents[2]
f=json.loads((root/'scripts/paperjs/curve-locations.json').read_text())['fixtures']
def point(p):return 'svg_path.Point('+', '.join(str(float(x)) for x in p)+')'
cs=['svg_path.CubicBezier('+', '.join(point(c[i:i+2]) for i in [0,2,4,6])+')' for c in f[0]['curves']]
s=['''// Adapted from pinned Paper.js CurveLocation.js; MIT notice in upstream file.
// Generated by generate-curve-locations.py. Offsets are measured prefix lengths.
import gleam/float
import gleam/io
import gleam/list
import gleam/result
import gleam/string
import svg_path
import svg_path/measure
fn probe(sp: svg_path.Subpath, index: Int, expected_distance: Float) -> Result(List(Float), svg_path.Error) {
 let at = case index { 3 -> svg_path.SubpathParameter(2, 1.0) _ -> svg_path.SubpathParameter(index, 0.0) }
 use prefix <- result.try(case index {
  0 -> Ok(svg_path.subpath_empty(at: svg_path.subpath_start(sp)))
  _ -> svg_path.subpath_between(sp, from: svg_path.SubpathParameter(0,0.0), to: at)
 })
 use distance <- result.try(measure.subpath_length(prefix))
 use point <- result.try(svg_path.subpath_point(sp, at: at))
 // Supplementary inverse check, using the upstream expected distance.
 use inverse <- result.try(measure.subpath_point_at_length(sp, distance: expected_distance))
 Ok([distance,point.x,point.y,inverse.x,inverse.y])
}
fn emit(label: String, value: Result(List(Float),svg_path.Error)) {
 let text = case value {
  Ok(values) -> "Ok([" <> string.join(list.map(values,float.to_string),",") <> "])"
  Error(error) -> string.inspect(Error(error))
 }
 io.println(label <> ":" <> text)
}
pub fn main() {''']
s.append('let cubic = svg_path.subpath_assert(['+','.join(cs)+'])')
s.append('let lines = svg_path.subpath_assert_polyline(['+','.join(point(p) for p in f[0]['points'])+'])')
for mode in ['cubic','lines']:
 for x in f:s.append(f'emit("{mode}-{x["id"]}",probe({mode},{x["nodeIndex"]},{float(x["expected"])}))')
s.append('}');(root/'test_paperjs/src/paper_curve_locations_probe.gleam').write_text('\n'.join(s)+'\n')
